export interface HttpClientOptions {
  maxAttempts?: 1 | 2 | 3
}

export async function request(url: string, init: RequestInit = {}, options: HttpClientOptions = {}): Promise<Response> {
  const method = (init.method ?? 'GET').toUpperCase()
  const retryable = method === 'GET' || method === 'HEAD'
  const maxAttempts = options.maxAttempts ?? 3
  let response = await fetch(url, init)
  for (let attempt = 1; attempt < maxAttempts && retryable && response.status >= 500; attempt += 1) {
    response = await fetch(url, init)
  }
  return response
}
import assert from 'node:assert/strict'
import { test } from 'node:test'

import { request } from './client.ts'

void test('GET respects the configured attempt cap', async () => {
  let attempts = 0
  const original = globalThis.fetch
  globalThis.fetch = async () => {
    attempts += 1
    return new Response(null, { status: 503 })
  }
  try {
    await request('https://example.test', { method: 'GET' }, { maxAttempts: 3 })
    assert.equal(attempts, 3)
  } finally {
    globalThis.fetch = original
  }
})

void test('POST does not retry', async () => {
  let attempts = 0
  const original = globalThis.fetch
  globalThis.fetch = async () => {
    attempts += 1
    return new Response(null, { status: 503 })
  }
  try {
    await request('https://example.test', { method: 'POST' }, { maxAttempts: 3 })
    assert.equal(attempts, 1)
  } finally {
    globalThis.fetch = original
  }
})
{
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test client.spec.ts"
  }
}

